Hub.GetPlayerDataMap = function(self)
	local m = self:GetRoundModule();
	if (m and (type(m.PlayerData) == "table")) then
		return m.PlayerData;
	end
	local rep = self.Services.ReplicatedStorage;
	for _, path in ipairs({"GetPlayerData","Remotes.Gameplay.GetPlayerData","Remotes.GetPlayerData"}) do
		local rem = rep;
		for part in path:gmatch("[^%.]+") do
			rem = rem and rem:FindFirstChild(part);
		end
		if (rem and rem:IsA("RemoteFunction")) then
			local ok, data = pcall(function()
				return rem:InvokeServer();
			end);
			if (ok and (type(data) == "table")) then
				return data;
			end
		end
	end
	return nil;
end;
Hub.IsRoundActive = function(self)
	local rtp = self.Services.Workspace:FindFirstChild("RoundTimerPart");
	if rtp then
		local cr = rtp:FindFirstChild("CurrentRound", true);
		if (cr and cr:IsA("TextLabel") and (cr.Text ~= "") and (cr.Text ~= LUAOBFUSACTOR_DECRYPT_STR_0("\127\16\145\219\51\210\95\28\55\140\220\56\216", "\43\60\101\227\169\86\188"))) then
			return false;
		end
	end
	local data = self:GetPlayerDataMap();
	if (data and (type(data) == "table") and (next(data) ~= nil)) then
		local hasActiveRole = false;
		for _, pData in pairs(data) do
			if ((type(pData) == "table") and pData.Role and (pData.Role ~= "") and (pData.Role ~= "Lobby") and not pData.Dead and not pData.Killed) then
				hasActiveRole = true;
				break;
			end
		end
		if not hasActiveRole then
			return false;
		end
		return true;
	end
	if self.Services.Workspace:FindFirstChild("GunDrop") then
		return true;
	end
	local coinContainer = self.Services.Workspace:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\83\199\216\177\121\195\183\35\113\193\223\186\72", "\87\16\168\177\223\58\172\217"), true);
