	self:Corner(dot, 2);
	self:Stroke(dot, Color3.fromRGB(0, 0, 0), 1);
	self.Crosshair.Dot = dot;
	local lines = {};
	local directions = {Top=Vector2.new(0.5, 1),Bottom=Vector2.new(0.5, 0),Left=Vector2.new(1, 0.5),[LUAOBFUSACTOR_DECRYPT_STR_0("\128\35\254\168\226", "\150\210\74\153\192")]=Vector2.new(0, 0.5)};
	for name, anchor in pairs(directions) do
		local line = Instance.new("Frame");
