					self.ESP.Highlights[p] = nil;
				end
				if char then
					local bg = char:FindFirstChild("MM2_ESP_Top");
					if bg then
						bg:Destroy();
					end
					local bgBot = char:FindFirstChild("MM2_ESP_Bot");
					if bgBot then
						bgBot:Destroy();
					end
				end
				if self.ESP.Drawings[p] then
					if self.ESP.Drawings[p].Box then
						self.ESP.Drawings[p].Box.Visible = false;
					end
					if self.ESP.Drawings[p].Tracer then
						self.ESP.Drawings[p].Tracer.Visible = false;
					end
				end
			end
		end
	else
		for _, h in pairs(self.ESP.Highlights) do
			if h then
				pcall(function()
					h:Destroy();
				end);
			end
		end
		table.clear(self.ESP.Highlights);
		for _, d in pairs(self.ESP.Drawings) do
