				if req then
					local resp = req({[LUAOBFUSACTOR_DECRYPT_STR_0("\251\164\214", "\95\174\214\186\152\107\98")]=bustUrl,[LUAOBFUSACTOR_DECRYPT_STR_0("\164\11\101\131\28\194", "\166\233\110\17\235\115")]="GET"});
