Hub.DecodeSkinEnum = function(self, raw)
	local group, item = string.match(raw, LUAOBFUSACTOR_DECRYPT_STR_0("\206\231\40\249\253\135\104\164\203\135\49\211\205\137\111\169\190\138\29\169\231\253\27\167\185\134", "\140\144\162\70"));
	if not group then
		return nil;
	end
	local ok, val = pcall(function()
		return Enum[group][item];
	end);
	return (ok and val) or nil;
end;
Hub.DecodeSkinProperty = function(self, current, raw)
	local k = type(raw);
	if ((k == "number") or (k == "boolean")) then
		return raw;
	end
	local want = typeof(current);
	if (k == "string") then
		if (want == LUAOBFUSACTOR_DECRYPT_STR_0("\245\38\76\127\199\196\45\84", "\142\176\72\57\18")) then
			return self:DecodeSkinEnum(raw);
		end
		return raw;
	end
	if (k ~= LUAOBFUSACTOR_DECRYPT_STR_0("\178\48\18\40\163", "\68\198\81\112")) then
		return nil;
	end
	if (want == "Vector3") then
		return Vector3.new(raw[1], raw[2], raw[3]);
	elseif (want == LUAOBFUSACTOR_DECRYPT_STR_0("\129\10\179\0\67\15\229", "\125\215\111\208\116\44")) then
		return Vector2.new(raw[1], raw[2]);
	elseif (want == "Color3") then
		return Color3.new(raw[1], raw[2], raw[3]);
	elseif (want == "NumberRange") then
		return NumberRange.new(raw[1], raw[2]);
	elseif (want == LUAOBFUSACTOR_DECRYPT_STR_0("\36\97\93\242\117\89", "\60\103\39\47\147\24")) then
		return CFrame.new(table.unpack(raw));
	elseif (want == LUAOBFUSACTOR_DECRYPT_STR_0("\194\31\250\130\211\225\125\233\27\226\133\216\240\75", "\46\140\106\151\224\182\147")) then
		local keys = {};
		for i = 1, #raw do
			local pt = raw[i];
			keys[i] = NumberSequenceKeypoint.new(pt.t, pt.v, pt.e or 0);
		end
		if (#keys < 2) then
			return NumberSequence.new((keys[1] and keys[1].Value) or 0);
		end
		return NumberSequence.new(keys);
	elseif (want == "ColorSequence") then
		local keys = {};
		for i = 1, #raw do
			local pt = raw[i];
			local rgb = pt.c;
			keys[i] = ColorSequenceKeypoint.new(pt.t, Color3.new(rgb[1], rgb[2], rgb[3]));
		end
		if (#keys < 2) then
			return ColorSequence.new((keys[1] and keys[1].Value) or Color3.new(1, 1, 1));
		end
		return ColorSequence.new(keys);
	end
	return nil;
end;
Hub.ApplySkinProps = function(self, inst, props)
	if (type(props) ~= "table") then
		return inst;
	end
	for key, raw in pairs(props) do
		if not skinPropNope[key] then
			local ok, curr = pcall(function()
				return inst[key];
			end);
			if ok then
				local val = self:DecodeSkinProperty(curr, raw);
				if (val ~= nil) then
					pcall(function()
						inst[key] = val;
					end);
				end
			end
		end
	end
	return inst;
end;
Hub.RegisterSkinGarbage = function(self, owner, inst)
	if (not owner or not inst) then
		return inst;
	end
	local list = self.SkinSystem.Musor[owner];
	if not list then
		list = {};
		self.SkinSystem.Musor[owner] = list;
	end
	list[#list + 1] = inst;
	return inst;
end;
Hub.ClearSkinGarbage = function(self, owner)
	local list = self.SkinSystem.Musor[owner];
	if not list then
		return;
	end
	for i = #list, 1, -1 do
		local inst = list[i];
		if inst then
			pcall(function()
				inst:Destroy();
			end);
		end
		list[i] = nil;
	end
end;
Hub.BackupSkinProp = function(self, inst, data)
	if not inst then
		return;
	end
	if not self.SkinSystem.Saved[inst] then
		self.SkinSystem.Saved[inst] = data;
	end
end;
