Hub.UnequipSkin = function(self, slot)
	self.SkinSystem.Picked[slot] = nil;
	if (slot == LUAOBFUSACTOR_DECRYPT_STR_0("\99\70\57\243\136", "\181\40\40\80\149\237\43\24")) then
		self.SkinSystem.CurrentKnife = LUAOBFUSACTOR_DECRYPT_STR_0("\59\189\43\55", "\114\117\210\69\82\218\42");
	else
		self.SkinSystem.CurrentGun = "None";
	end
	local tool = self:FindToolBySlot(slot);
	local display = self:FindDisplayPedestal(slot);
	if tool then
		self:ClearSkinGarbage(tool);
	end
	if display then
		self:ClearSkinGarbage(display);
	end
	for inst, data in pairs(self.SkinSystem.Saved) do
		if (inst and inst.Parent) then
			if data.grip then
				pcall(function()
					inst.Grip = data.grip;
				end);
			end
			if data.size then
				pcall(function()
					inst.Size = data.size;
				end);
			end
			if data.trans then
				pcall(function()
					inst.Transparency = data.trans;
				end);
			end
			if data.mod then
				pcall(function()
					inst.LocalTransparencyModifier = data.mod;
				end);
			end
			if data.volume then
				pcall(function()
					inst.Volume = data.volume;
				end);
			end
		end
		self.SkinSystem.Saved[inst] = nil;
	end
