	bBtn.TextSize = 10;
	bBtn.AutoButtonColor = false;
	bBtn.Parent = bindRow;
	self:Corner(bBtn, 5);
	self:Stroke(bBtn, Color3.fromRGB(40, 40, 52), 1);
