Hub.PlayCatalogAnimation = function(self, assetId, category)
	local char = self.Services.Players.LocalPlayer.Character;
	local hum = char and char:FindFirstChildOfClass("Humanoid");
	if not hum then
		return;
	end
	self:StopAnimation();
	task.spawn(function()
		local realAnimId = self:ResolveAnimationId(assetId);
		local anim = Instance.new(LUAOBFUSACTOR_DECRYPT_STR_0("\84\2\168\164\3\157\0\122\2", "\105\21\108\193\201\98\233"));
		anim.AnimationId = realAnimId;
		local animator = hum:FindFirstChildOfClass("Animator") or hum;
		local track = animator:LoadAnimation(anim);
		if ((category == "Animations") or (category == "Walk Styles")) then
			track.Priority = Enum.AnimationPriority.Movement;
			track.Looped = true;
			track:Play();
			self.Animations.CurrentTrack = track;
			self.Animations.EmoteTrack = nil;
		else
			track.Priority = Enum.AnimationPriority.Action4;
			track.Looped = true;
			track:Play();
			self.Animations.CurrentTrack = track;
			self.Animations.EmoteTrack = track;
		end
	end);
end;
Hub.StopAnimation = function(self)
	if self.Animations.CurrentTrack then
		pcall(function()
			self.Animations.CurrentTrack:Stop();
		end);
		self.Animations.CurrentTrack = nil;
	end
	self.Animations.EmoteTrack = nil;
	local lp = self.Services.Players.LocalPlayer;
	local char = lp.Character;
	local hum = char and char:FindFirstChildOfClass("Humanoid");
	local animator = hum and hum:FindFirstChildOfClass("Animator");
	if animator then
		for _, t in ipairs(animator:GetPlayingAnimationTracks()) do
			if ((t.Priority == Enum.AnimationPriority.Action) or (t.Priority == Enum.AnimationPriority.Action4)) then
				pcall(function()
					t:Stop();
				end);
			end
		end
	end
end;
